import{_ as r,o as a,c as d,a2 as l}from"./chunks/framework.CqpfiAoK.js";const g=JSON.parse('{"title":"قانون العمل التكافلي","description":"","frontmatter":{},"headers":[],"relativePath":"ar/41-共生劳动法.md","filePath":"ar/41-共生劳动法.md"}'),e={name:"ar/41-共生劳动法.md"};function i(o,t,n,s,h,b){return a(),d("div",null,[...t[0]||(t[0]=[l('<h1 id="قانون-العمل-التكافلي" tabindex="-1">قانون العمل التكافلي <a class="header-anchor" href="#قانون-العمل-التكافلي" aria-label="Permalink to &quot;قانون العمل التكافلي&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>41</td></tr><tr><td>الوحدة</td><td>النظام القانوني وإطار الحوكمة</td></tr><tr><td>الكلمات المفتاحية</td><td>العمل التكافلي، الأكثر عملاً الأكثر أجراً، حقوق العمل، التعاقد المشترك على الإنتاج، مناهضة الاستغلال</td></tr></tbody></table><h2 id="أولاً-الغرض-التشريعي-والمبادئ-الأساسية" tabindex="-1">أولاً: الغرض التشريعي والمبادئ الأساسية <a class="header-anchor" href="#أولاً-الغرض-التشريعي-والمبادئ-الأساسية" aria-label="Permalink to &quot;أولاً: الغرض التشريعي والمبادئ الأساسية&quot;">​</a></h2><p><em>قانون العمل التكافلي</em> أحد القوانين المحورية في النظام القانوني لحضارة التكافل المرساة، ويقف إلى جانب <em>الدستور التكافلي</em>. يهدف إلى تنظيم جميع أنشطة العمل والمساهمة داخل كون هنغ يوان، وإرساء نظام التوزيع القائم على «الأكثر عملاً الأكثر أجراً؛ النمو الذاتي والتطور الذاتي»، واستئصال تربة الاستغلال الافتراسي على المستوى القانوني.</p><p>يحدد هذا القانون المبادئ الأساسية التالية:</p><table tabindex="0"><thead><tr><th>المبدأ</th><th>المضمون</th></tr></thead><tbody><tr><td>كرامة العمل</td><td>جميع الأعمال المشروعة محمية بالقانون؛ ولا يجوز انتهاك الكرامة الشخصية للعامل</td></tr><tr><td>الأكثر عملاً الأكثر أجراً</td><td>أجر العمل مرتبط مباشرة بحجم المساهمة؛ كلما زادت المساهمة زاد الدخل؛ والكسب بلا عمل محظور</td></tr><tr><td>العمل الطوعي</td><td>العمل القسري والاسترقاق محظوران؛ وللعمال الحق في اختيار محتوى العمل وطريقته بحرية</td></tr><tr><td>الأجر العادل</td><td>أجر متساوٍ عن عمل متساوٍ؛ ويُحظر التمييز في الأجور على أساس العرق أو الزراعة أو الأصل</td></tr><tr><td>ضمان العمل</td><td>على الدولة والحضارة واجب توفير بيئة عمل آمنة وضمان اجتماعي أساسي للعمال</td></tr><tr><td>التعاون التكافلي</td><td>يُشجع التعاون والتآزر بين العمال؛ وتُعارض المنافسة الضارة والألعاب ذات المحصلة الصفرية</td></tr></tbody></table><h2 id="ثانياً-الحقوق-الأساسية-للعمال" tabindex="-1">ثانياً: الحقوق الأساسية للعمال <a class="header-anchor" href="#ثانياً-الحقوق-الأساسية-للعمال" aria-label="Permalink to &quot;ثانياً: الحقوق الأساسية للعمال&quot;">​</a></h2><p>يمنح قانون العمل التكافلي جميع أشكال الحياة ذات القدرة على العمل داخل كون هنغ يوان الحقوق التالية:</p><ol><li><strong>حق المساواة في التوظيف</strong>: لا يجوز تمييز أي كائن في البحث عن عمل أو التوظيف على أساس العرق أو الزراعة أو الأصل أو الجنس أو عوامل أخرى.</li><li><strong>حق حرية اختيار المهنة</strong>: للعامل الحق في اختيار المهنة والمنصب ومكان العمل وفق إرادته وقدرته، والحق في تغيير المهنة وفقاً للقانون.</li><li><strong>حق الأجر المعقول</strong>: للعامل الحق في الحصول على أجر يتناسب مع مساهمته في العمل؛ ولا يجوز أن يقل الأجر عن الحد الأدنى المضمون الذي تحدده الحضارة.</li><li><strong>حق الراحة والإجازات</strong>: للعامل الحق في ترتيبات معقولة لساعات العمل وإجازات دورية؛ ويُحظر التمديد غير المحدود لساعات العمل.</li><li><strong>حق السلامة المهنية</strong>: للعامل الحق في العمل في بيئة آمنة وصحية؛ ويجب على جهة العمل توفير شروط حماية مهنية مطابقة للمعايير.</li><li><strong>حق التدريب المهني</strong>: للعامل الحق في تلقي التدريب المهني والإرشاد الزراعي؛ وعلى جهة العمل والدولة واجب توفير موارد التدريب.</li><li><strong>حق التنظيم والمشاورة</strong>: للعامل الحق في تأسيس أو الانضمام إلى جمعيات العمال وفقاً للقانون، والحق في حماية مصالحه عبر المشاورة الجماعية.</li><li><strong>حق التظلم والإنصاف</strong>: عند انتهاك حقوق العمل، يحق للعامل تقديم التظلمات والدعاوى إلى هيئات التحكيم العمالي ومحكمة التكافل.</li></ol><h2 id="ثالثاً-إضفاء-الصفة-القانونية-على-آلية-التعاقد-المشترك-على-الإنتاج" tabindex="-1">ثالثاً: إضفاء الصفة القانونية على آلية التعاقد المشترك على الإنتاج <a class="header-anchor" href="#ثالثاً-إضفاء-الصفة-القانونية-على-آلية-التعاقد-المشترك-على-الإنتاج" aria-label="Permalink to &quot;ثالثاً: إضفاء الصفة القانونية على آلية التعاقد المشترك على الإنتاج&quot;">​</a></h2><p>آلية التعاقد المشترك على الإنتاج هي النظام المحوري لتوزيع الموارد في حضارة التكافل المرساة؛ ويكرسها <em>قانون العمل التكافلي</em> في شكل قانوني:</p><ul><li><strong>أطراف التعاقد</strong>: أي كائن لديه القدرة على العمل يمكن أن يكون طرفاً متعاقداً؛ ويمكن للفرد أو الجماعة التعاقد معاً.</li><li><strong>محتوى التعاقد</strong>: يشمل على سبيل المثال لا الحصر تطوير موارد الزراعة، وصيانة الأبعاد، ونقل المعرفة، والبحث التقني، والخدمات العامة وغيرها من المجالات.</li><li><strong>مدة التعاقد</strong>: تحدد وفق طبيعة المحتوى المتعاقد عليه؛ التعاقد القصير من سنة إلى ثلاث سنوات، والطويل من خمس إلى عشرين سنة، مع إمكانية التجديد عند انتهاء المدة.</li><li><strong>توزيع العائدات</strong>: عائد المتعاقد مرتبط مباشرة بالإنتاج؛ يقدم جزء من الإنتاج إلى التراكم العام، والباقي ملك للمتعاقد.</li><li><strong>آلية الخروج</strong>: للمتعاقد الحق في الخروج من التعاقد بعد إشعار مسبق في مدة معقولة؛ ولا يجوز تقييده قسراً في علاقة التعاقد.</li><li><strong>حل النزاعات</strong>: تُحل نزاعات التعاقد أولوية عبر التحكيم العمالي؛ ومن لا يقبل نتيجة التحكيم يمكنه رفع دعوى إلى محكمة التكافل.</li></ul><h2 id="رابعاً-الحماية-الخاصة-للعمل" tabindex="-1">رابعاً: الحماية الخاصة للعمل <a class="header-anchor" href="#رابعاً-الحماية-الخاصة-للعمل" aria-label="Permalink to &quot;رابعاً: الحماية الخاصة للعمل&quot;">​</a></h2><p>مراعاةً للاحتياجات الخاصة لأشكال الحياة المختلفة داخل كون هنغ يوان، ينشئ هذا القانون نظام الحماية الخاصة للعمل:</p><table tabindex="0"><thead><tr><th>المجموعة المحمية</th><th>إجراءات الحماية الخاصة</th></tr></thead><tbody><tr><td>المزارعون المبتدئون</td><td>لا يجوز تكليفهم بأعمال عالية الخطورة تتجاوز قدراتهم؛ ويجب توفير إرشاد الموجهين</td></tr><tr><td>الكائنات الأنثوية في فترة الحمل والولادة</td><td>الحق في إجازة أمومة مدفوعة الأجر لا تقل عن ستة أشهر؛ ولا يجوز تكليفهن بأعمال عالية الشدة أثناء الرضاعة</td></tr><tr><td>الكائنات ذوات الإعاقة والمصابون</td><td>الحق في تعديل معقول لمنصب العمل وضمان بيئة عمل خالية من العوائق</td></tr><tr><td>العمال من الأعراق الأخرى</td><td>يجب على جهة العمل احترام الخصائص الفسيولوجية والعادات الثقافية للأعراق الأخرى وتوفير ظروف عمل ملائمة</td></tr><tr><td>العمال المسنون</td><td>يمكنهم عند بلوغ سن معينة طلب تخفيف شدة العمل أو الانتقال إلى مناصب استشارية</td></tr></tbody></table><h2 id="خامساً-المسؤولية-القانونية-وضمانات-التنفيذ" tabindex="-1">خامساً: المسؤولية القانونية وضمانات التنفيذ <a class="header-anchor" href="#خامساً-المسؤولية-القانونية-وضمانات-التنفيذ" aria-label="Permalink to &quot;خامساً: المسؤولية القانونية وضمانات التنفيذ&quot;">​</a></h2><p>تتحمل جهات العمل المخالفة لأحكام هذا القانون المسؤوليات التالية حسب جسامة الظروف:</p><ol><li>دفع الأجر المستحق للعامل والتعويض (التعويض من مرة إلى ثلاث مرات قيمة الأجر المتأخر).</li><li>إصدار أمر بالتصحيح خلال مهلة محددة؛ وفي حال عدم التصحيح تُفرض غرامة.</li><li>في الحالات الجسيمة، يُلغى ترخيص التشغيل ويُمنع المسؤولون من مزاولة الأعمال الإدارية لمدة معينة.</li><li>إذا شكل الفعل جريمة، تُطبق المسؤولية الجنائية وفقاً للقانون.</li></ol><p>تنشئ الدولة هيئات تفتيش عمالية مسؤولة عن الإشراف والتفتيش على التزام جهات العمل بقانون العمل. ولجمعيات العمال الحق في تمثيل العمال في التفتيش العمالي والمشاورة الجماعية.</p><h2 id="الخاتمة" tabindex="-1">الخاتمة <a class="header-anchor" href="#الخاتمة" aria-label="Permalink to &quot;الخاتمة&quot;">​</a></h2><p><em>قانون العمل التكافلي</em> هو الناقل القانوني لفلسفة «الأكثر عملاً الأكثر أجراً» لحضارة التكافل المرساة. يحول العمل من موضوع استغلال إلى حق محترم، والتوزيع من استحواذ افتراسي إلى مقابل قائم على المساهمة، مضعاً أساساً مؤسسياً متيناً للعمل من أجل تقدم عشرة آلاف عرق معاً.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>40-共生宪法总纲 (الدستور التكافلي: المبادئ العامة)</li><li>06-多劳多得分配原理 (مبادئ توزيع الأكثر عملاً الأكثر أجراً)</li><li>22-资源分配联产承包机制 (آلية التعاقد المشترك على الإنتاج لتوزيع الموارد)</li><li>42-消费者保护法 (قانون حماية المستهلك)</li></ul>',23)])])}const _=r(e,[["render",i]]);export{g as __pageData,_ as default};
